const menu = document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Menyunu aç':'Menyunu bağla');document.querySelector('#navigation').classList.toggle('is-open',!open)});
document.querySelector('#navigation').addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menyunu aç');document.querySelector('#navigation').classList.remove('is-open')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menyunu aç');document.querySelector('#navigation').classList.remove('is-open');menu.focus()}});

const I=d=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const ARR=I('<path d="m9 5 7 7-7 7"/>'),ARR2=I('<path d="M5 12h14M13 6l6 6-6 6"/>');
const services=[
 {slug:'urologiya',name:'Urologiya',img:'urologiya',intro:'Urologiya robotik cərrahiyyənin ən geniş tətbiq olunduğu sahələrdən biridir. Xüsusilə çanaq boşluğu kimi məhdud anatomik sahələrdə robotik sistemlərin hərəkət dəqiqliyi cərraha əlavə imkanlar yaradır. Robotik üsulla aşağıdakı əməliyyatlar həyata keçirilə bilir:',items:['Radikal prostatektomiya – prostat xərçəngi zamanı prostat vəzinin çıxarılması','Parsial nefrektomiya – böyrək şişlərində böyrəyin sağlam hissəsinin qorunaraq yalnız şişin çıxarılması','Radikal nefrektomiya – göstəriş olduqda böyrəyin çıxarılması','Pieloplastika – böyrək və sidik axarı arasındakı daralmanın aradan qaldırılması','Radikal sistektomiya – sidik kisəsi xərçəngində sidik kisəsinin çıxarılması']},
 {slug:'ginekologiya',name:'Ginekologiya',img:'ginekologiya',intro:'Robotik cərrahiyyə müxtəlif xoşxassəli və onkoloji ginekoloji xəstəliklərin cərrahi müalicəsində istifadə oluna bilər. Robotik alətlərin yüksək hərəkət imkanları çanaq daxilində dəqiq disseksiya və tikişlərin aparılmasına kömək edir. Tətbiq sahələrinə aşağıdakılar daxildir:',items:['Histerektomiya – uşaqlığın çıxarılması','Miomektomiya – uşaqlıq qorunmaqla miomaların çıxarılması','Endometriozun cərrahi müalicəsi','Uşaqlıq və endometrium xərçənginin cərrahi müalicəsi','Seçilmiş hallarda digər mürəkkəb ginekoloji əməliyyatlar']},
 {slug:'umumi-cerrahiyye',name:'Ümumi cərrahiyyə',img:'umumi-cerrahiyye',intro:'Robotik texnologiyalar ümumi cərrahiyyədə də geniş tətbiq imkanlarına malikdir. Xüsusilə mürəkkəb rekonstruktiv əməliyyatlarda və dəqiq tikiş tələb edən müdaxilələrdə robotik yanaşmadan istifadə oluna bilər. Əsas tətbiq sahələri:',items:['Qasıq və qarın divarı yırtıqlarının cərrahi müalicəsi','Mədə və bağırsaq əməliyyatları','Kolorektal cərrahiyyə','Reflüks və hiatal yırtıq əməliyyatları','Öd kisəsi əməliyyatları','Seçilmiş bariatrik və metabolik cərrahiyyə prosedurları']},
 {slug:'torakal-cerrahiyye',name:'Torakal cərrahiyyə',img:'torakal-cerrahiyye',intro:'Robotik sistemlər döş qəfəsi daxilində aparılan bəzi əməliyyatlarda da istifadə edilir. Kiçik kəsiklər vasitəsilə döş qəfəsinə daxil olmaq və incə anatomik strukturlar ətrafında dəqiq işləmək mümkün olur. Tətbiq sahələrinə:',items:['Ağciyərin müəyyən hissəsinin çıxarılması','Mediastinal törəmələrin əməliyyatları','Seçilmiş ağciyər şişlərinin cərrahi müalicəsi'],outro:'daxildir.'},
 {slug:'urek-damar-cerrahiyyesi',name:'Ürək-damar cərrahiyyəsi',img:'urek-damar-cerrahiyyesi',intro:'Robotik cərrahiyyə seçilmiş ürək-damar əməliyyatlarının minimal invaziv üsulla icrasına imkan verən müasir cərrahi yanaşmadır. Robotik sistemlər yüksək dəqiqlikli üçölçülü görüntüləmə və geniş hərəkət diapazonuna malik cərrahi alətlər vasitəsilə mürəkkəb anatomik sahələrdə dəqiq manipulyasiyaların aparılmasını təmin edir. Robotik ürək cərrahiyyəsində daha çox:',items:['Mitral qapaq əməliyyatları','Koronar bypass əməliyyatları','Ürəkdaxili törəmələrin çıxarılması','Ürək qüsurları əməliyyatları'],outro:'və s. aparılır.'}
];
const whatIs='Robotik cərrahiyyə müasir minimal invaziv cərrahiyyənin inkişaf etmiş istiqamətlərindən biridir. Bu üsulda cərrah xüsusi konsoldan robotik sistemi idarə edir və sistem incə, çevik cərrahi alətlər vasitəsilə əməliyyatı həyata keçirir. Robotik sistem cərrahın hərəkətlərini yüksək dəqiqliklə cərrahi alətlərə ötürür. Yüksək keyfiyyətli, böyüdülmüş və üç ölçülü görüntüləmə isə cərraha əməliyyat sahəsini daha detallı görməyə və mürəkkəb anatomik strukturlar üzərində daha kontrollu işləməyə imkan verir.';
const faqs=[
 ['Əməliyyatı robot həyata keçirir?','<p>Xeyr. Robotik cərrahiyyədə əməliyyatı robot deyil, cərrah həyata keçirir. Robotik sistem cərrahın idarə etdiyi texnoloji platformadır. Cərrah konsol vasitəsilə bütün hərəkətləri özü idarə edir, əməliyyatın gedişinə və qəbul edilən qərarlara tam nəzarət edir. Başqa sözlə, robot cərrahı əvəz etmir cərrahın imkanlarını genişləndirir.</p>'],
 ['Robotik cərrahiyyənin üstünlükləri nələrdir?','<p>Robotik sistemin əsas üstünlüklərindən biri cərraha əməliyyat sahəsini böyüdülmüş və üçölçülü görüntü ilə qiymətləndirmək imkanı verməsidir. Bu, xüsusilə dar və mürəkkəb anatomik sahələrdə incə strukturların daha aydın vizuallaşdırılmasına kömək edə bilər. Robotik alətlərin çevikliyi və hərəkət imkanları cərrahın əl və bilək hərəkətlərini daha kontrollu şəkildə həyata keçirməsinə imkan yaradır. Sistem həmçinin cərrahın təbii əl hərəkətlərini kompüter vasitəsilə dəqiq şəkildə cərrahi alətlərə ötürür. Robotik cərrahiyyə minimal invaziv yanaşmaya əsaslandığı üçün uyğun əməliyyatlarda daha kiçik kəsiklərdən istifadə edilir. Bunun nəticəsində bəzi pasiyentlərdə əməliyyatdan sonrakı ağrı və sağalma müddəti daha az olur. Lakin bu üstünlüklər əməliyyatın növündən və pasiyentin fərdi xüsusiyyətlərindən asılıdır.</p>'],
 ['Robotik cərrahiyyə hansı sahələrdə tətbiq olunur?','<p>Robotik cərrahiyyə müxtəlif cərrahi ixtisaslarda tətbiq imkanına malikdir. Əsasən:</p><ul><li>Urologiya</li><li>Ümumi cərrahiyyə</li><li>Kolorektal cərrahiyyə</li><li>Ginekologiya</li><li>Torakal cərrahiyyə</li><li>Onkoloji cərrahiyyə</li><li>Ürək-damar cərrahiyyəsi</li><li>Baş-boyun və LOR cərrahiyyəsi</li><li>Pediatrik cərrahiyyənin seçilmiş sahələri</li></ul><p>və s. daxildir.</p>'],
 ['Robotik cərrahiyyə bütün pasiyentlər üçün uyğundur?','<p>Xeyr. Robotik cərrahiyyənin uyğunluğu hər pasiyent üçün fərdi şəkildə qiymətləndirilir. Diaqnoz, əməliyyatın növü, xəstəliyin mərhələsi, pasiyentin ümumi sağlamlıq vəziyyəti və digər klinik amillər nəzərə alınır.</p>'],
 ['Robotik cərrahiyyədə cərrahın rolu nədir?','<p>Cərrah əsas qərarverici və idarəedici şəxsdir. Robotik sistem cərrahı əvəz etmir, onun təcrübəsini və texniki imkanlarını dəstəkləyir. Əməliyyatın planlaşdırılması, robotun idarə olunması və cərrahi qərarlar cərrah tərəfindən həyata keçirilir.</p>'],
 ['Robotik cərrahiyyə daha az ağrılıdır?','<p>Uyğun əməliyyatlarda daha kiçik kəsiklərdən istifadə edildiyi üçün toxuma travması və əməliyyatdan sonrakı narahatlıq daha az olduğu üçün əməliyyatdan sonrakı bərpa daha tez olur və ağrı daha az olur.</p>']
];
const about=['Ege Hospital Robotik Cərrahiyyə Mərkəzi müasir cərrahiyyənin imkanlarını qabaqcıl robotik texnologiya ilə birləşdirən ixtisaslaşmış cərrahiyyə mərkəzidir. Mərkəzimizdə müasir tibbin təqdim etdiyi texnoloji imkanları cərrahların peşəkar təcrübəsi ilə birləşdirərək pasiyentlərə müasir, təhlükəsiz və fərdi yanaşma təqdim edirik. Robotik cərrahiyyə müasir minimal invaziv cərrahiyyənin inkişaf etmiş istiqamətlərindən biridir. Robotik sistem cərrah tərəfindən idarə olunur və əməliyyat zamanı yüksək görüntüləmə, daha geniş vizual nəzarət və incə, dəqiq hərəkət imkanları təqdim edərək mürəkkəb cərrahi prosedurların daha kontrollu şəkildə həyata keçirilməsinə dəstək olur. Mərkəzimizdə robotik cərrahiyyə texnologiyasından urologiya, ümumi cərrahiyyə, ginekologiya, kolorektal cərrahiyyə, torakal cərrahiyyə, onkoloji cərrahiyyə və digər uyğun cərrahi sahələrdə istifadə imkanları vardır. Robotik yanaşmanın tətbiqi hər bir pasiyentin sağlamlıq vəziyyəti, diaqnozu, əməliyyatın növü və tibbi göstərişlər nəzərə alınmaqla fərdi şəkildə müəyyən edilir.',
'Ege Hospital Robotik Cərrahiyyə Mərkəzində müasir texnologiya, multidissiplinar tibbi yanaşma və cərrahların peşəkar təcrübəsi bir araya gətirilir. Bizim üçün robotik cərrahiyyə yalnız qabaqcıl texnologiya demək deyil. Əsas dəyər texnologiyanın cərrahın bilik, təcrübə və qərarvermə imkanları ilə birləşməsindədir. Robotik sistem cərrahı əvəz etmir, cərrahın idarə etdiyi texnologiya onun imkanlarını genişləndirir və mürəkkəb prosedurların həyata keçirilməsinə dəstək olur.',
'Məqsədimiz müasir robotik texnologiyanı cərrahların peşəkar təcrübəsi ilə birləşdirərək Azərbaycanda müasir cərrahiyyənin inkişafına töhfə vermək, təhlükəsiz və pasiyent yönümlü cərrahiyyə xidmətləri təqdim etmək və robotik cərrahiyyə sahəsində bilik və təcrübənin artırılması, həkimlər arasında elmi əməkdaşlığın və multidissiplinar yanaşmanın inkişaf etdirilməsi, yeni texnologiyaların klinik praktikaya inteqrasiyası istiqamətində davamlı fəaliyyət göstərməkdir.'];
