const drCards=()=>doctors.map(d=>{const inner=`<div class="dr-photo">${d.photo?`<img src="/assets/${d.photo}" alt="${d.name}" loading="lazy">`:`<svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="46" r="22"/><path d="M16 120c0-28 20-44 44-44s44 16 44 44Z"/></svg>`}</div><h3>${d.name}</h3><p>${d.role}</p>`;return d.href?`<a class="dr-card" href="${d.href}">${inner}</a>`:`<div class="dr-card${d.test?' is-test':''}">${inner}</div>`}).join('');
